# %% ../nbs/02_server.ipynb #cf7b0350
def pub_ports():
    "Return public ports reserved by Solveit"
    return set(map(int, json.loads(os.environ.get('PUBLIC_DOMAINS', '{}'))))

def free_port(start=6550, skip=(), host='localhost'):
    "Find first free port >= `start`, excluding `skip`"
    skip = set(skip)
    return first(p for p in range(start, 65536) if p not in skip and is_port_free(p, host))

