def srv_bundle(srv): return srv,srv.app,srv.app.route,get_preview(srv.app, srv.port)

def _server_target(srv=None, port=8000, reuse=True, host='localhost'):
    own = False
    if srv: return srv,port,own
    if port is None: port = free_port(6551, skip=pub_ports(), host=host)
    found,_ = find_server(port)
    if found:
        if not reuse: raise RuntimeError(f"Server already running on port {port}")
        return found,port,own
    if not is_port_free(port): raise RuntimeError(f"Port {port} in use but no JupyUvi instance found in namespace")
    return None,port,True

def _ensure_server(srv=None, port=8000, app=None, app_kw=None, reuse=True, **jupyuvi_kw):
    srv,port,own = _server_target(srv, port, reuse, jupyuvi_kw.get('host', 'localhost'))
    if srv:
        if not is_serving(srv): raise RuntimeError(f"Server on port {srv.port} is not serving")
        return (*srv_bundle(srv), own)
    srv = JupyUvi(app or mk_app(app_kw), port=port, **jupyuvi_kw)
    return (*srv_bundle(srv), own)

async def _ensure_server_a(srv=None, port=8000, app=None, app_kw=None, reuse=True, **jupyuvi_kw):
    srv,port,own = _server_target(srv, port, reuse, jupyuvi_kw.get('host', 'localhost'))
    if srv:
        if not await is_serving_a(srv): raise RuntimeError(f"Server on port {srv.port} is not serving")
        return (*srv_bundle(srv), own)
    srv = JupyUviAsync(app or mk_app(app_kw), port=port, **jupyuvi_kw)
    await srv.start()
    return (*srv_bundle(srv), own)

# %% ../nbs/02_server.ipynb #a36bb7b0
def ensure_server(srv=None, port=8000, app=None, app_kw=None, **jupyuvi_kw):
    "Return a live server, served app, route decorator, and preview helper; existing servers win"
    srv,app,rt,p,_ = _ensure_server(srv=srv, port=port, app=app, app_kw=app_kw, reuse=True, **jupyuvi_kw)
    return srv,app,rt,p

async def ensure_server_a(srv=None, port=8000, app=None, app_kw=None, **jupyuvi_kw):
    "Return a live async server, served app, route decorator, and preview helper; existing servers win"
    srv,app,rt,p,_ = await _ensure_server_a(srv=srv, port=port, app=app, app_kw=app_kw, reuse=True, **jupyuvi_kw)
    return srv,app,rt,p

