@asynccontextmanager
async def serve_app(
    app=None, # FastHTML app to serve; if omitted, create one with `app_kw`
    port=8000, # Port to serve on; `None` chooses a free non-public port
    srv=None, # Existing server to use; must already be live
    reuse=True, # Reuse an existing live server on `port`
    after_start=None, # Optional callback run after server is available
    before_stop=None, # Optional callback run before owned-server teardown
    restore_routes=True, # Restore `app.routes` after the block for owned servers
    timeout=5, # Seconds to wait for owned server port to become free
    app_kw=None, # Keyword args for default app creation
    **jupyuvi_kw):
    "Yield a live JupyUviAsync server for a test block; reuse only when allowed, cleanup only when owned, restore owned routes"
    srv,app,rt,p,own = await _ensure_server_a(srv=srv, port=port, app=app, app_kw=app_kw, reuse=reuse, **jupyuvi_kw)
    routes,err = list(app.routes) if own and restore_routes and hasattr(app, 'routes') else None,None
    try:
        if after_start: await maybe_await(after_start(srv))
        yield srv
    except Exception as e: err = e
    try:
        if before_stop: await maybe_await(before_stop(srv))
    except Exception as e:
        if err is None: err = e
    try:
        if routes is not None: app.routes[:] = routes
    except Exception as e:
        if err is None: err = e
    if own:
        srv.server.should_exit = True
        deadline = (loop := asyncio.get_running_loop()).time() + timeout
        while not is_port_free(srv.port, srv.host):
            if loop.time() > deadline:
                e = TimeoutError(f"Port {srv.host}:{srv.port} still in use after {timeout}s")
                if err is None: err = e
                break
            await asyncio.sleep(0.1)
    if err: raise err
